/* ============================================
   INTERRUPT CARD COMPONENT
   A human-in-the-loop checkpoint: a question
   from the agent, a detail slot, and option
   buttons in a footer.

   The card is deliberately quiet — one tone,
   the standard container border, no status
   colour. The question and its buttons are
   the signal; the visually hidden status
   announcement carries the waiting state.
   ============================================ */

.ds-interrupt-card {
  --ds-interrupt-card-color: var(--color-icon-secondary);

  display: flex;
  flex-direction: column;
  width: 100%;
  background-color: var(--ds-chat-card-bg);
  border: var(--ds-chat-card-border);
  /* The chat furniture's shared 24px shell — see ToolCall. */
  border-radius: var(--ds-chat-card-radius);
  overflow: hidden;
}

/* Bare: the host panel is the surface, so the card keeps only its own
   padding and layout. */
.ds-interrupt-card--bare {
  background-color: transparent;
  border: none;
  border-radius: 0;
}

/* ============================================
   HEADER
   ============================================ */

.ds-interrupt-card__header {
  display: flex;
  align-items: flex-start;
  gap: var(--gap-200);
  /* 8px under the text: with the next section's 8px above, every seam in
     the card is 16px, MessageCard's body-to-actions distance; 12px at
     the card's top and bottom edges, every chat card's. */
  padding: var(--ds-chat-card-edge) var(--ds-chat-card-inset) var(--padding-200);
}

/* A section that closes the card takes the full bottom padding back. */
.ds-interrupt-card__header:last-child,
.ds-interrupt-card__detail:last-child {
  padding-bottom: var(--ds-chat-card-edge);
}

.ds-interrupt-card__icon {
  display: inline-flex;
  align-items: center;
  flex: none;
  /* A title's icon trails it, so the card's text starts on its inset edge. */
  order: 1;
  margin-inline-start: auto;
  /* Centre the icon on the title's first line. */
  margin-top: calc((var(--font-title-body-line-height) - var(--icon-size-500)) / 2);
  color: var(--ds-interrupt-card-color);
}

.ds-interrupt-card__icon .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-interrupt-card__heading {
  display: flex;
  flex-direction: column;
  /* The description is the title's subline, set straight under it. */
  gap: var(--ds-chat-card-gap-subline);
  min-width: 0;
}

/* The chat cards share one title tier, the scale's card-title role:
   a heading tier inside a reply would outrank the reply's own text. */
.ds-interrupt-card__title {
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  letter-spacing: var(--font-title-body-letter-spacing);
  color: var(--color-text-primary);
}

.ds-interrupt-card__description {
  margin: 0;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-secondary);
}

/* ============================================
   DETAIL SLOT
   Typically a pending ToolCall showing what
   wants to run.
   ============================================ */

.ds-interrupt-card__detail {
  /* Under the heading's 8px, so what the question covers sits 8px under
     it like the description does; 8px below meets the footer's 8px. */
  padding: 0 var(--ds-chat-card-inset) var(--padding-200);
}

.ds-interrupt-card__detail > :first-child {
  margin-top: 0;
}

.ds-interrupt-card__detail > :last-child {
  margin-bottom: 0;
}

/* No card in a card: the ToolCall the question covers sheds its shell and
   its rows sit on this card's inset, so the call reads as a line of the
   question rather than a card inside it. */
.ds-interrupt-card__detail > .ds-tool-call {
  border: none;
  border-radius: 0;
  background-color: transparent;
}

.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__content,
.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__actions {
  padding-inline: 0;
}

/* The call is a line of the question here, not a row of its own. */
.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__header {
  min-height: 0;
  padding: 0;
}

.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__header:hover {
  background-color: transparent;
}

/* The call's details, opened. A card has one footer and the decision owns
   it, so the code does not bring a footer of its own: it sits in a quiet
   well (the fill one step in from the card's, at MessageCard's media-slot
   corner, no border, so a slot rather than a card) with Copy in the well's
   corner, and the panel drops its divider, the card's only rule. */
.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__content {
  padding-block: var(--ds-chat-card-gap-text) 0;
  border-top: none;
}

.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__content > .ds-code-block {
  position: relative;
  border-radius: var(--ds-chat-card-radius-edge);
  background-color: var(--color-bg-container-secondary);
}

.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__content > .ds-code-block .ds-code-block__header {
  position: absolute;
  inset-block-start: var(--padding-200);
  inset-inline-end: var(--padding-200);
  margin: 0;
}

/* CodeBlock's own quiet copy, not the footer button a lone ToolCall
   draws, since the well is not a footer. */
.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__content > .ds-code-block .ds-code-block__copy {
  height: auto;
  padding: var(--padding-050) var(--padding-200);
  border: none;
  color: var(--color-text-secondary);
}

.ds-interrupt-card__detail > .ds-tool-call .ds-tool-call__content > .ds-code-block .ds-code-block__pre {
  padding: var(--ds-chat-card-edge);
}

/* ============================================
   OPTIONS
   Mirrors ToolCall's actions footer exactly, so
   a decision on a card and an approval on a
   call read as the same row.
   ============================================ */

.ds-interrupt-card__options {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: var(--gap-200);
  padding: var(--padding-200) var(--ds-chat-card-inset) var(--ds-chat-card-edge);
}

/* ============================================
   ANSWERED
   Same footer geometry, a status badge where
   the buttons were.
   ============================================ */

.ds-interrupt-card__answer {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  /* The footer's geometry, with the badge where the buttons were. */
  padding: var(--padding-200) var(--ds-chat-card-inset) var(--ds-chat-card-edge);
}

/* The read-out: the chosen button as a record. A compact Button's height,
   pill, padding, gap, type and icon size, so it sits where the buttons were
   without a jump, filled in the status the choice records instead of the
   action colour, so it reads as done rather than pressable. */
.ds-interrupt-card__readout {
  --ds-interrupt-card-readout-bg: var(--color-status-neutral-bg);
  --ds-interrupt-card-readout-text: var(--color-status-neutral-text);

  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--gap-200);
  height: var(--control-height-compact);
  padding: 0 var(--padding-300);
  border-radius: var(--radius-pill);
  background-color: var(--ds-interrupt-card-readout-bg);
  color: var(--ds-interrupt-card-readout-text);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  white-space: nowrap;
}

.ds-interrupt-card__readout--positive {
  --ds-interrupt-card-readout-bg: var(--color-status-positive-bg);
  --ds-interrupt-card-readout-text: var(--color-status-positive-text);
}

.ds-interrupt-card__readout--error {
  --ds-interrupt-card-readout-bg: var(--color-status-error-bg);
  --ds-interrupt-card-readout-text: var(--color-status-error-text);
}

.ds-interrupt-card__readout-icon {
  --icon-size: var(--icon-size-500);

  color: inherit;
}

/* ============================================
   VISUALLY HIDDEN
   The waiting announcement is for screen
   readers only.
   ============================================ */

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-interrupt-card .material-symbols-rounded {
  color: inherit;
}

import React from 'react';
import { Button } from '../Button/Button';
import './InterruptCard.css';
import '../../behaviors/chat-card.css';
import '../../behaviors/visually-hidden.css';
import '../../fonts/material-symbols.css';
import { mirrorClass } from '../../behaviors/direction';

/** The status an answered card records: an approval, a refusal, or neither. */
export type InterruptCardAnsweredVariant = 'positive' | 'error' | 'neutral';

/** One choice the card offers, rendered as a Button in the options footer. */
export interface InterruptCardOption {
  /** Value passed to `onValueChange` when this option is chosen. */
  value: string;
  /** Button text, e.g. "Allow once". */
  label: string;
  /**
   * Visual weight: `primary` for the recommended choice, `secondary` (the
   * default) for the rest. `danger` is the legacy value from before colour
   * moved onto `tone`, and renders as `variant="secondary" tone="destructive"`.
   */
  variant?: 'primary' | 'secondary' | 'danger';
  /** Colour, passed to the option's Button: `destructive` for dangerous approvals. */
  tone?: 'default' | 'destructive';
  /**
   * The status the answered card's read-out takes once this option is chosen.
   * Defaults to `positive` for a `primary` option, `error` for a destructive
   * one and `neutral` for the rest; set `error` on a refusal such as "Deny".
   */
  answeredVariant?: InterruptCardAnsweredVariant;
  /**
   * What the answered card's read-out says once this option is chosen,
   * written as the decision made rather than the button pressed, e.g.
   * "Denied" for "Deny". Defaults to `label`.
   */
  answeredLabel?: string;
}

/** The status an answered option records, from its own or its emphasis. */
function answeredVariantOf(option: InterruptCardOption | undefined): InterruptCardAnsweredVariant {
  if (!option) return 'neutral';
  if (option.answeredVariant) return option.answeredVariant;
  if (option.variant === 'danger' || option.tone === 'destructive') return 'error';
  return option.variant === 'primary' ? 'positive' : 'neutral';
}

/**
 * The Button emphasis and tone an option renders with, legacy `danger`
 * included. In a row of three or more, the last option is the way out and
 * takes ActionCard's Dismiss treatment, secondary in the neutral tone,
 * unless it names a tone of its own.
 */
function optionButtonProps(option: InterruptCardOption, wayOut = false) {
  if (option.variant === 'danger') {
    return { variant: 'secondary', tone: option.tone ?? 'destructive' } as const;
  }
  const variant = option.variant ?? 'secondary';
  const tone = option.tone ?? (wayOut && variant === 'secondary' ? 'neutral' : 'default');
  return { variant, tone } as const;
}

/** Props owned by InterruptCard itself — everything else falls through to the root element. */
type InterruptCardOwnProps = {
  /**
   * The question, e.g. "Allow file edit?".
   * Note: this shadows the native `title` tooltip attribute, which InterruptCard does not expose.
   */
  title: string;
  /** One line of context under the title. */
  description?: string;
  /** Leading Material Symbol name, or any custom element. No icon by default. */
  icon?: string | React.ReactNode;
  /** The choices, rendered as buttons left to right. */
  options?: InterruptCardOption[];
  /** Fires with the chosen option's value. */
  onValueChange?: (value: string) => void;
  /**
   * The already-chosen value. When set, the card renders its answered state:
   * the options give way to the chosen one's read-out, worded as the
   * decision made, in the status that choice records.
   */
  value?: string;
  /** Override the answered read-out's text (default: the chosen option's `answeredLabel`, then its label). */
  answeredLabel?: string;
  /** Visually hidden status announced while the card waits for a decision. Defaults to "Waiting for your decision". */
  waitingLabel?: string;
  /** Additional CSS classes */
  className?: string;
  /**
   * Detail slot between the description and the options — typically a
   * `<ToolCall status="pending">` showing what wants to run.
   */
  children?: React.ReactNode;
  /** Strip the card chrome (fill, border, radius) when the card sits inside another panel that supplies the surface, such as AiButton's request panel. */
  bare?: boolean;
};

export interface InterruptCardProps
  extends InterruptCardOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof InterruptCardOwnProps> {}

/**
 * InterruptCard is a human-in-the-loop checkpoint: a question from the agent
 * with option buttons for the person to decide. "Allow this file edit?" —
 * allow once, always allow, deny.
 *
 * The card stays quiet in both states: one tone, the standard container
 * border, options in a footer outside the content. Once `value` is set the
 * decision is made: the buttons give way to the chosen one's read-out, a
 * compact button's size and shape in the status the option records
 * (`answeredVariant`); a visually hidden
 * status announcement carries the waiting state for screen readers.
 *
 * Fully controlled: the card never stores the answer itself — `onValueChange`
 * reports the choice and `value` renders it.
 */
export const InterruptCard = React.forwardRef<HTMLDivElement, InterruptCardProps>(
  (
    {
      title,
      description,
      icon,
      options,
      onValueChange,
      value,
      answeredLabel,
      waitingLabel = 'Waiting for your decision',
      className = '',
      children,
      bare = false,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-interrupt-card';
    const answered = value !== undefined;

    const classes = [
      baseClass,
      answered ? `${baseClass}--answered` : '',
      bare ? `${baseClass}--bare` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const chosen = answered ? options?.find((option) => option.value === value) : undefined;
    const echoedLabel = answeredLabel ?? chosen?.answeredLabel ?? chosen?.label ?? value;

    return (
      <div {...rest} ref={ref} role="group" aria-label={title} className={classes}>
        <div className={`${baseClass}__header`}>
          {icon && (
            <span className={`${baseClass}__icon`} aria-hidden="true">
              {typeof icon === 'string' ? (
                <span className={`material-symbols-rounded ${mirrorClass(icon)}`}>{icon}</span>
              ) : (
                icon
              )}
            </span>
          )}
          <div className={`${baseClass}__heading`}>
            <span className={`${baseClass}__title`}>{title}</span>
            {description && <p className={`${baseClass}__description`}>{description}</p>}
          </div>
          {!answered && (
            <span className="ds-visually-hidden" role="status">
              {waitingLabel}
            </span>
          )}
        </div>

        {children && <div className={`${baseClass}__detail`}>{children}</div>}

        {answered ? (
          /* The decision is made: the buttons give way to the chosen one's
             read-out, a compact button's size and shape in the status that
             choice records, behind a check (a cross for a refusal). */
          <div className={`${baseClass}__answer`}>
            <span className={`${baseClass}__readout ${baseClass}__readout--${answeredVariantOf(chosen)}`}>
              <span className={`${baseClass}__readout-icon material-symbols-rounded`} aria-hidden="true">
                {answeredVariantOf(chosen) === 'error' ? 'close' : 'check'}
              </span>
              {echoedLabel}
            </span>
          </div>
        ) : (
          options &&
          options.length > 0 && (
            <div className={`${baseClass}__options`}>
              {options.map((option, index) => (
                <Button
                  key={option.value}
                  {...optionButtonProps(option, index === options.length - 1 && options.length >= 3)}
                  size="compact"
                  label={option.label}
                  onClick={() => onValueChange?.(option.value)}
                />
              ))}
            </div>
          )
        )}
      </div>
    );
  },
);

InterruptCard.displayName = 'InterruptCard';
